"use client";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState, useEffect } from "react";
import { st } from "@/utils/styling";
import AuthModal from "./AuthModal";

const navItems = [
  { href: "/", label: "Accueil" },
  { href: "/medecins", label: "Médecins" },
  { href: "/services", label: "Services" },
  { href: "/rendez-vous", label: "Rendez-vous" },
  { href: "/contact", label: "Contact" },
  { href: "/urgences", label: "Urgences" },
  { href: "/paiement", label: "Paiement" },
  { href: "/chatbot", label: "Chatbot IA" },
];

export default function Navbar() {
  const pathname = usePathname();
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState<{ firstName: string } | null>(null);

  useEffect(() => {
    // Check if user is logged in
    fetch("/api/auth/me")
      .then(res => res.json())
      .then(data => {
        if (data.user) {
          setIsLoggedIn(true);
          setUser(data.user);
        }
      })
      .catch(() => {});
  }, []);

  const handleLogout = async () => {
    await fetch("/api/auth/logout", { method: "POST" });
    setIsLoggedIn(false);
    setUser(null);
    window.location.href = "/";
  };

  return (
    <>
      <header className="sticky top-0 z-40 border-b border-slate-200 bg-white/90 backdrop-blur">
        <div className="mx-auto max-w-7xl px-6 py-4 flex items-center justify-between">
          <Link href="/" className="font-semibold text-xl text-slate-800">
            <span className="text-blue-600">Medi</span>Care
          </Link>
          <nav className="hidden md:flex gap-6 text-sm">
            {navItems.map((item) => {
              const active = pathname === item.href;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={st(
                    "transition-colors",
                    active
                      ? "text-blue-600 font-semibold"
                      : "text-slate-600 hover:text-slate-900"
                  )}
                >
                  {item.label}
                </Link>
              );
            })}
          </nav>
          <div className="flex items-center gap-3">
            {isLoggedIn ? (
              <>
                <Link
                  href="/espace-patient"
                  className="text-sm text-slate-600 hover:text-slate-900"
                >
                  Bonjour, {user?.firstName}
                </Link>
                <button
                  onClick={handleLogout}
                  className="text-sm text-slate-600 hover:text-slate-900"
                >
                  Déconnexion
                </button>
              </>
            ) : (
              <button
                onClick={() => setIsAuthModalOpen(true)}
                className="text-sm text-slate-600 hover:text-slate-900 font-medium"
              >
                Se connecter
              </button>
            )}
            <Link
              href="/rendez-vous"
              className="inline-flex items-center rounded-md bg-blue-600 text-white px-4 py-2 text-sm font-medium shadow-sm hover:bg-blue-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600"
            >
              Prendre rendez-vous
            </Link>
          </div>
        </div>
      </header>
      
      <AuthModal 
        isOpen={isAuthModalOpen} 
        onClose={() => setIsAuthModalOpen(false)} 
      />
    </>
  );
}
